styles:
.reader-quote {
  font-style: normal;
  color: #ff00ff;
  text-shadow: 0 0 8px #ff00ff, 0 0 16px rgba(255, 0, 255, 0.5);
  font-weight: 600;
  letter-spacing: 1px;
}
.reader-ellipsis {
  letter-spacing: 8px;
  color: #00ffff;
  text-shadow: 0 0 6px #00ffff;
}
.reader-dash {
  letter-spacing: 4px;
  color: #00ffff;
  text-shadow: 0 0 6px #00ffff;
}
.reader-speak {
  color: #00ffff;
  font-weight: 700;
  text-shadow: 0 0 10px #00ffff, 0 0 20px rgba(0, 255, 255, 0.3);
  text-transform: uppercase;
}
.reader-body :deep(.reader-dropcap) {
  float: left;
  font-size: 3.4em;
  line-height: 0.7;
  padding-right: 8px;
  padding-top: 4px;
  color: #00ffff;
  font-weight: 900;
  text-shadow: 2px 0 #ff00ff, -2px 0 #00ff00;
  font-family: 'Courier New', monospace;
}
